const handleCalculatorInput = (input) => {
    if (input === 'C') {
        expression = '';
        updateDisplay('0');
        return;
    }
    if (input === '⌫') {
        expression = expression.slice(0, -1);
        updateDisplay(expression || '0');
        return;
    }
    if (input === '=') {
        const result = safeEval(expression);
        expression = result === 'Error' ? '' : String(result);
        updateDisplay(result);
        return;
    }
    if (input === 'π') {
        expression += 'π';
    } else if (input === 'e') {
        expression += 'e';
    } else if (input === '√') {
        expression += '√(';
    } else if (input === '^') {
        expression += '^';
    } else if (['sin', 'cos', 'tan', 'ln', 'log'].includes(input)) {
        expression += `${input}(`;
    } else {
        expression += input;
    }
    updateDisplay(expression);
};

