    sqrt: (x) => Math.sqrt(x),
    abs: (x) => Math.abs(x),
    exp: (x) => Math.exp(x),
};

const buildEvalExpression = (displayValue, evalValue = displayValue) => {
    displayExpression += displayValue;
    evalExpression += evalValue;
};

const safeEval = (expression) => {
    try {
        if (/[^0-9+\-*/().%,^\sA-Za-z]/.test(expression)) return 'Error';
        const sanitized = expression
            .replace(/π/g, 'Math.PI')
            .replace(/Exp\(/g, 'exp(')
            .replace(/\^/g, '**')
            .replace(/log\(/g, 'log(')
            .replace(/ln\(/g, 'ln(')
            .replace(/√\(/g, 'sqrt(');

        const result = Function(
            'sin',
            'cos',
            'tan',
            'asin',
            'acos',
            'atan',
            'sinh',
            'cosh',
            'tanh',
            'log',
