            evalExpression = evalExpression.slice(0, -1);
            updateDisplay(displayExpression || '0');
            break;
        case 'deg':
            mode = 'deg';
            updateModeDisplay();
            break;
        case 'rad':
            mode = 'rad';
            updateModeDisplay();
            break;
        case '=': {
            const result = safeEval(evalExpression);
            displayExpression = result === 'Error' ? '' : String(result);
            evalExpression = result === 'Error' ? '' : String(result);
            updateDisplay(result);
            break;
        }
        case 'π':
            buildEvalExpression('π', 'Math.PI');
            updateDisplay(displayExpression);
            break;
        case 'e':
            buildEvalExpression('e', 'Math.E');
            updateDisplay(displayExpression);
            break;
