            buildEvalExpression('√(', 'sqrt(');
            updateDisplay(displayExpression);
            break;
        case 'Exp':
            buildEvalExpression('Exp(', 'exp(');
            updateDisplay(displayExpression);
            break;
        case 'sin':
        case 'cos':
        case 'tan':
        case 'asin':
        case 'acos':
        case 'atan':
        case 'sinh':
        case 'cosh':
        case 'tanh':
        case 'ln':
        case 'log':
            buildEvalExpression(`${input}(`, `${input}(`);
            updateDisplay(displayExpression);
            break;
        case '^':
            buildEvalExpression('^', '^');
            updateDisplay(displayExpression);
            break;
        case '%':
            buildEvalExpression('%', '%');
            updateDisplay(displayExpression);
            break;
        default:
            buildEvalExpression(input, input);
            updateDisplay(displayExpression);
            break;
    }
};

export const initCalculator = () => {
    renderCalculator();
};
