const buildEvalExpression = (displayValue, evalValue = displayValue) => {
    displayExpression += displayValue;
    evalExpression += evalValue;
};

const safeEval = (expression) => {
    try {
        if (/[^0-9+\-*/().%,^\sA-Za-z]/.test(expression)) return 'Error';
        const sanitized = expression
            .replace(/π/g, 'Math.PI')
            .replace(/Exp\(/g, 'exp(')
            .replace(/\^/g, '**')
            .replace(/log\(/g, 'log(')
            .replace(/ln\(/g, 'ln(')
            .replace(/√\(/g, 'sqrt(');

        const result = Function(
            'sin',
            'cos',
            'tan',
            'asin',
            'acos',
            'atan',
            'sinh',
            'cosh',
            'tanh',
            'log',
            'ln',
            'sqrt',
            'abs',
            'exp',
            'pow',
            'Math',
            `"use strict"; return (${sanitized})`
        )(
            mathFunctions.sin,
            mathFunctions.cos,
            mathFunctions.tan,
            mathFunctions.asin,
            mathFunctions.acos,
            mathFunctions.atan,
            mathFunctions.sinh,
            mathFunctions.cosh,
            mathFunctions.tanh,
            mathFunctions.log,
            mathFunctions.ln,
            mathFunctions.sqrt,
            mathFunctions.abs,
            mathFunctions.exp,
            Math.pow,
            Math
        );

        return Number.isFinite(result) ? result : 'Error';
    } catch {
        return 'Error';
    }
};

const renderCalculator = () => {
    const calculatorRoot = qs('#calculator');
    if (!calculatorRoot) return;

    const calculator = createElement('div', { className: 'calculator' });
    calculator.innerHTML = `
        <div class="calculator-screen">
            <div id="calcMode" class="calculator-mode">${mode.toUpperCase()}</div>
            <div id="calcDisplay" class="calculator-display">0</div>
        </div>
        <div class="calculator-buttons"></div>
    `;

    const buttonsContainer = calculator.querySelector('.calculator-buttons');
    buttons.forEach((label) => {
        const button = createElement('button', { className: 'calculator-button', textContent: label });
        button.type = 'button';
        button.addEventListener('click', () => handleCalculatorInput(label));
        buttonsContainer.appendChild(button);
    });

    calculatorRoot.appendChild(calculator);
};

const updateDisplay = (value) => {
    const display = qs('#calcDisplay');
    if (display) display.textContent = value;
};

const updateModeDisplay = () => {
    const modeDisplay = qs('#calcMode');
    if (modeDisplay) modeDisplay.textContent = mode.toUpperCase();
};

const handleCalculatorInput = (input) => {
    switch (input) {
        case 'C':
            displayExpression = '';
            evalExpression = '';
            updateDisplay('0');
            break;
        case '⌫':
            displayExpression = displayExpression.slice(0, -1);
            evalExpression = evalExpression.slice(0, -1);
            updateDisplay(displayExpression || '0');
            break;
        case 'deg':
            mode = 'deg';
            updateModeDisplay();
            break;
        case 'rad':
            mode = 'rad';
            updateModeDisplay();
            break;
        case '=': {
            const result = safeEval(evalExpression);
            displayExpression = result === 'Error' ? '' : String(result);
            evalExpression = result === 'Error' ? '' : String(result);
            updateDisplay(result);
            break;
        }
        case 'π':
            buildEvalExpression('π', 'Math.PI');
            updateDisplay(displayExpression);
            break;
        case 'e':
            buildEvalExpression('e', 'Math.E');
            updateDisplay(displayExpression);
            break;
        case '√':
            buildEvalExpression('√(', 'sqrt(');
            updateDisplay(displayExpression);
            break;
        case 'Exp':
            buildEvalExpression('Exp(', 'exp(');
            updateDisplay(displayExpression);
            break;
        case 'sin':
        case 'cos':
        case 'tan':
        case 'asin':
        case 'acos':
        case 'atan':
        case 'sinh':
        case 'cosh':
        case 'tanh':
        case 'ln':
        case 'log':
            buildEvalExpression(`${input}(`, `${input}(`);
            updateDisplay(displayExpression);
            break;
        case '^':
            buildEvalExpression('^', '^');
            updateDisplay(displayExpression);
            break;
        case '%':
            buildEvalExpression('%', '%');
            updateDisplay(displayExpression);
            break;
        default:
            buildEvalExpression(input, input);
            updateDisplay(displayExpression);
            break;
    }
};

export const initCalculator = () => {
    renderCalculator();
};

