    except Exception as exc:
        saved.append({
            "source_file": str(docx_path).replace("\\", "/"),
            "error": f"DOCX extract failed: {exc}",
            "type": "docx",
        })
    return saved


def extract_from_pdf(pdf_path: Path, subject_dir: Path) -> list[dict]:
    saved = []
    try:
        import fitz  # PyMuPDF
    except Exception:
        return [{
            "source_file": str(pdf_path).replace("\\", "/"),
            "error": "PyMuPDF not installed. Install with: pip install pymupdf",
            "type": "pdf",
        }]

    try:
        doc = fitz.open(pdf_path)
        img_count = 0
        for page_idx in range(len(doc)):
            page = doc[page_idx]
            images = page.get_images(full=True)
            for local_idx, img in enumerate(images, start=1):
                xref = img[0]
                base = doc.extract_image(xref)
                raw = base.get("image", b"")
                ext = base.get("ext", "bin")
                if not raw:
                    continue
                img_count += 1
                out_name = (
                    f"{slugify(pdf_path.stem)}_p{page_idx + 1:03d}_img{local_idx:03d}.{ext}"
                )
                out_path = subject_dir / out_name
                out_path.write_bytes(raw)
                saved.append({
                    "source_file": str(pdf_path).replace("\\", "/"),
                    "output_file": str(out_path).replace("\\", "/"),
                    "type": "pdf",
                    "page": page_idx + 1,
                })
        doc.close()
        if img_count == 0:
            saved.append({
                "source_file": str(pdf_path).replace("\\", "/"),
                "type": "pdf",
                "note": "No embedded images found",
            })
    except Exception as exc:
        saved.append({
            "source_file": str(pdf_path).replace("\\", "/"),
            "error": f"PDF extract failed: {exc}",
            "type": "pdf",
        })
    return saved


def collect_files(root: Path) -> list[Path]:
    files = []
    for ext in ("*.pdf", "*.docx"):
        files.extend(root.rglob(ext))
    return sorted(files)


def main() -> None:
    parser = argparse.ArgumentParser(description="Extract subject-wise diagram images from PDF and DOCX source files.")
    parser.add_argument("--src", default="sourcefiles-ce/Aptransco_sourcefiles", help="Source folder containing study files")
    parser.add_argument("--out", default="images/source-diagrams", help="Output folder for extracted images")
    parser.add_argument("--report", default="scripts/diagram_extract_report.json", help="JSON report path")
    parser.add_argument("--clean", action="store_true", help="Delete output folder before extraction")
    args = parser.parse_args()

    src_root = Path(args.src)
    out_root = Path(args.out)
    report_path = Path(args.report)

    if not src_root.exists():
        raise SystemExit(f"Source folder not found: {src_root}")

    if args.clean and out_root.exists():
        shutil.rmtree(out_root)

    ensure_dir(out_root)
    ensure_dir(report_path.parent)

    files = collect_files(src_root)
    results = []
    counts_by_subject = defaultdict(int)
    files_by_subject = defaultdict(int)

    for path in files:
        subject = detect_subject(path)
        subject_slug = slugify(subject)
        subject_dir = out_root / subject_slug
        ensure_dir(subject_dir)
        files_by_subject[subject] += 1

        if path.suffix.lower() == ".docx":
            extracted = extract_from_docx(path, subject_dir)
        elif path.suffix.lower() == ".pdf":
            extracted = extract_from_pdf(path, subject_dir)
        else:
            extracted = []

        for item in extracted:
            item["subject"] = subject
            if "output_file" in item:
                counts_by_subject[subject] += 1
            results.append(item)

    report = {
        "source_root": str(src_root).replace("\\", "/"),
        "output_root": str(out_root).replace("\\", "/"),
        "total_input_files": len(files),
        "files_by_subject": dict(sorted(files_by_subject.items())),
        "images_by_subject": dict(sorted(counts_by_subject.items())),
        "total_images": sum(counts_by_subject.values()),
        "results": results,
    }

    report_path.write_text(json.dumps(report, indent=2), encoding="utf-8")

    print("Extraction complete")
    print(f"Input files: {report['total_input_files']}")
    print(f"Total images extracted: {report['total_images']}")
    for subject, count in sorted(report["images_by_subject"].items()):
        print(f"  {subject}: {count}")
    print(f"Report: {report_path}")


if __name__ == "__main__":
    main()

