def analyse_page(page) -> dict:
    drawings = page.get_drawings()
    total    = len(drawings)
    if total == 0:
        return {"total": 0, "diag": 0, "zones": [0] * ZONE_ROWS}

    ph = page.rect.height
    zh = ph / ZONE_ROWS
    zones = [0] * ZONE_ROWS
    diag  = 0

    for d in drawings:
        r = d.get("rect")
